import { useState } from 'react';
import { JxChip, JxTagInput } from '@jinx-ui/react';

interface ArticleTagsPickerProps {
  value?: string[];
  defaultValue?: string[];
  onChange?: (tags: string[]) => void;
  label?: string;
  placeholder?: string;
}

export default function ArticleTagsPicker({
  value,
  defaultValue = [],
  onChange,
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
}: ArticleTagsPickerProps) {
  const [inner, setInner] = useState<string[]>(defaultValue);
  const tags = value ?? inner;

  const commit = (next: string[]) => {
    if (value === undefined) setInner(next);
    onChange?.(next);
  };

  const add = (next: string[]) => {
    const unique: string[] = [];
    for (const tag of next) {
      const trimmed = tag.trim();
      if (trimmed && !unique.includes(trimmed)) unique.push(trimmed);
    }
    commit(unique);
  };

  const remove = (tag: string) => commit(tags.filter((item) => item !== tag));

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
      <JxTagInput
        ariaLabel={label}
        placeholder={placeholder}
        value={tags}
        onValueChange={add}
      />

      {tags.length > 0 ? (
        <div
          role="list"
          aria-label="Выбранные теги"
          style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}
        >
          {tags.map((tag) => (
            <span key={tag} role="listitem" style={{ display: 'inline-flex' }}>
              <JxChip active removable onRemove={() => remove(tag)}>
                {tag}
              </JxChip>
            </span>
          ))}
        </div>
      ) : (
        <span
          style={{
            color: 'var(--jx-text-2)',
            font: 'inherit',
            fontFamily: 'var(--jx-font-sans)',
            fontSize: '13px',
          }}
        >
          Тегов пока нет — введите слово и нажмите Enter, чтобы добавить первый.
        </span>
      )}
    </div>
  );
}

